import{_ as a,c as o,a0 as t,o as r}from"./chunks/framework.B6JXc2q-.js";const b=JSON.parse('{"title":"ADR-0006：WebUI 播放请求与在线搜索引用边界","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0006-webui-playback-contract.md","filePath":"adr/0006-webui-playback-contract.md"}'),i={name:"adr/0006-webui-playback-contract.md"};function c(l,e,d,n,s,p){return r(),o("div",null,e[0]||(e[0]=[t('<h1 id="adr-0006-webui-播放请求与在线搜索引用边界" tabindex="-1">ADR-0006：WebUI 播放请求与在线搜索引用边界 <a class="header-anchor" href="#adr-0006-webui-播放请求与在线搜索引用边界" aria-label="Permalink to &quot;ADR-0006：WebUI 播放请求与在线搜索引用边界&quot;">​</a></h1><ul><li><strong>状态</strong>：Accepted（代码级实现与定点验证通过；服务器/实机验收不在本包）</li><li><strong>日期</strong>：2026-09-24</li></ul><h2 id="上下文" tabindex="-1">上下文 <a class="header-anchor" href="#上下文" aria-label="Permalink to &quot;上下文&quot;">​</a></h2><p>主页曾通过任意 options 字典发送未声明的 <code>prefer_codec</code> 与 <code>search_key</code>，在严格的 <code>PlayOptionsModel(extra=&quot;forbid&quot;)</code> 下产生 422。在线搜索插件实际返回 MusicFree 私有 <code>IMusicItem</code>，不能直接暴露给 WebUI。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to &quot;决策&quot;">​</a></h2><ol><li>WebUI 使用与 <code>PlayOptionsModel</code> 对齐的 typed <code>PlayOptions</code>，主页请求由 typed builder 构造；后端继续拒绝未知字段。</li><li>在线搜索结果只有携带正式 <code>play_reference</code>（已声明的 query、source_hint 和严格 options）时才允许进入 <code>/api/v1/play</code>。</li><li>缺少正式引用时，WebUI 不以标题、搜索词或插件私有 item 冒充播放身份，也不向 WebUI 暴露媒体 URL、cookie、token 或原始插件错误。</li><li>本工作包只新增一个内置 <code>OnlinePluginSourcePlugin</code> 与进程内有 TTL/容量上限的 opaque 引用存储；不新增通用插件框架、不引入 play/session 全链路。</li></ol><h2 id="后果" tabindex="-1">后果 <a class="header-anchor" href="#后果" aria-label="Permalink to &quot;后果&quot;">​</a></h2><p>链接播放和在线搜索播放路径均由前后端定点契约测试和 CI 门禁保护。当前不新增 <code>online_plugin</code> delivery proxy fallback：<code>DeliveryAdapter</code>/Mina 路径没有证明能以解析 headers 完成代理取流；该问题留待独立 delivery 设计。测试服务器、真实入口及实机播放仍需独立验收，不能由代码级测试替代。</p>',8)]))}const h=a(i,[["render",c]]);export{b as __pageData,h as default};
